	section	"CODE",code
	xref	_m6809_step
	xref	_m6809_rd_slow
	xref	_m6809_wr_slow
	xref	_m6809_idle_hit

; int32_t m6809_run_asm(M6809 *c, int32_t cycles)
	public	_m6809_run_asm
	cnop	0,4
_m6809_run_asm:
