	move.l	48(sp),a5
	move.l	52(sp),d0
	add.l	d0,4112(a5)
	move.l	4112(a5),d7
	move.l	d7,-(sp)                     ; the start value (0(sp))
	clr.b	4210(a5)                 ; idle loops: the world may have changed
	bsr	load_regs
	tst.l	d7
	ble	exit_loop
	bra	check_ints

; registers from the struct (and the table pointers)
load_regs:
	lea	2048(a5),a2
	lea	3072(a5),a1
	lea	optab,a6
	moveq	#0,d3
	move.b	4193(a5),d3
	move.b	4190(a5),d4
	move.b	4191(a5),d5
	moveq	#0,d6
	move.w	4160(a5),d6
	moveq	#0,d0
	move.w	4168(a5),d0
	move.w	d0,d2
	lsr.w	#8,d2
	move.l	(a2,d2.w*4),a3
