; registers into the struct
store_regs:
	move.b	d3,4193(a5)
	move.b	d4,4190(a5)
	move.b	d5,4191(a5)
	move.w	d6,4160(a5)
	move.l	a4,d0
	sub.l	a3,d0
	move.w	d0,4168(a5)
	move.l	d7,4112(a5)
	rts

; an interrupt pending, CWAI/SYNC waiting or the free run mode: one step of the C core
check_ints:
	tst.l	d7
	ble	exit_loop
	tst.b	4199(a5)
	bne.s	c_step
	tst.b	4200(a5)
	bne.s	c_step
	tst.b	4197(a5)
	bne.s	c_step
	btst	#6,d3
	bne.s	.nofirq
	tst.b	4195(a5)
	bne.s	c_step
.nofirq:
	btst	#4,d3
	bne.s	dispatch
	tst.b	4196(a5)
	bne.s	c_step
dispatch:
