_m6809_tr_next:
tr_next:
	move.l	12420(a5),d0
	beq.s	dispatch_plain
tr_look:
	move.l	a4,d1
	sub.l	a3,d1
	tst.w	d1
	bpl.s	dispatch_plain
	and.l	#$7fff,d1
	move.l	d0,a0
	move.l	(a0,d1.l*4),d0
